dashboard.css:
/* Sundown. Structural CSS only: Superset's markdown sanitizer drops class and style. Rules on
   elements Superset paints itself say !important, or Superset's own equal-specificity rule wins. */
/* ground and tiles */
.dashboard-component-tabs,
.dashboard-component-tabs .dashboard-component-tabs-content { background-color: #F7F7F7 !important; }
.dashboard-component-tabs { box-shadow: none !important; }
.dashboard .dashboard-component-tabs { padding-left: 0 !important; }
.dashboard-component-chart-holder { border: 1px solid #EBEBEB; border-radius: 2px; }
.background--white { border: 1px solid #EBEBEB; border-radius: 2px; }
.background--white .dashboard-component-chart-holder { border: 0; }
.dashboard-component-chart-holder .header-controls { opacity: 0; transition: opacity .15s; }
.dashboard-component-chart-holder:hover .header-controls { opacity: 1; }
/* masthead: a navy band, white wordmark */
.background--white:has(.dashboard-markdown h2) { background-color: #06474D !important; border-color: #06474D !important; }
.background--white:has(.dashboard-markdown h2) .dashboard-component-chart-holder { background-color: #06474D !important; }
.dashboard-markdown h2 { font-size: 26px; font-weight: 700; letter-spacing: -.01em; margin: 0; color: #FFFFFF; }
.dashboard-markdown h2 + p { font-size: 13.5px; color: #B9DCDD; margin: 4px 0 0; }
.dashboard-markdown h2 + p code { background: rgba(255,255,255,.12); color: #FFFFFF; }
[data-test-chart-name="Data through"] { text-align: right; position: relative; }
[data-test-chart-name="Data through"] .header-title { font-size: 11.5px !important; font-weight: 500 !important;
  color: #B9DCDD !important; justify-content: flex-end; transform: translateX(16px); }
[data-test-chart-name="Data through"] .header-title a { color: #B9DCDD !important; }
[data-test-chart-name="Data through"] .superset-legacy-chart-big-number { align-items: flex-end !important; }
[data-test-chart-name="Data through"] .text-container { align-items: flex-end !important; }
[data-test-chart-name="Data through"] .header-controls { position: absolute; right: 0; }
/* filter bar: 'More filters' as an outline button, not the theme's filled primary tint */
[data-test="dropdown-container-btn"] { background: transparent !important; border: 1px solid #DDDDDD !important;
  color: #6A6A6A !important; box-shadow: none !important; }
[data-test="dropdown-container-btn"]:hover { border-color: #6A6A6A !important; color: #222222 !important; }
[data-test="dropdown-container-btn"] .ant-badge-count { background: #F0F0F0 !important; color: #6A6A6A !important; box-shadow: none !important; }
/* tabs: inactive secondary, active ink on an accent underline */
.dashboard-component-tabs .ant-tabs-nav::before { border-bottom: 1px solid #DDDDDD; }
.dashboard-component-tabs .anchor-link-container { display: none; }
.dashboard-component-tabs .ant-tabs-tab { font-size: 14.5px; padding: 10px 0; color: #6A6A6A; }
.dashboard-component-tabs .ant-tabs-tab-btn, .dashboard-component-tabs .dragdroppable-tab { padding: 0 !important; margin: 0 !important; }
.dashboard-component-tabs .ant-tabs-tab-active .ant-tabs-tab-btn { font-weight: 600; color: #222222 !important; }
.dashboard-component-tabs .ant-tabs-ink-bar { background: #FF385C !important; height: 3px !important; }
.dashboard-component-tabs .ant-tabs-nav { margin-bottom: 14px !important; }  /* clear of the KPI cards' accent edge */
/* section bands: a full-width band in the masthead colour, an accent left edge, white caps */
.dashboard-component-header { background: #06474D !important; border-left: 5px solid #FF385C !important;
  border-radius: 2px; padding: 0 14px !important; min-height: 34px; margin-top: 10px; display: flex !important;
  align-items: center !important; }
.dashboard-component-header .editable-title, .dashboard-component-header .editable-title input { font-size: 13.5px !important;
  font-weight: 600 !important; color: #FFFFFF !important; letter-spacing: .07em !important; text-transform: uppercase; }
.dashboard-component-header .anchor-link-container { display: none !important; }
/* the one-line colour keys */
.dashboard-markdown:has(h5) .dashboard-component-chart-holder,
.dashboard-markdown:has(h6) .dashboard-component-chart-holder { background-color: transparent !important; border: 0 !important; }
.dashboard-markdown h5 { font-size: 12px; font-weight: 400; color: #6A6A6A; margin: 0; }
.dashboard-markdown h6 { font-size: 13px; font-weight: 500; color: #6A6A6A; margin: 0; }
.dashboard-markdown h6 strong { color: #222222; font-weight: 600; }
.dashboard-markdown [itemprop]::before { content: ""; display: inline-block; width: 10px; height: 10px;
  border-radius: 2px; margin: 0 6px 0 2px; vertical-align: -1px; }
.dashboard-markdown [itemprop="this"]::before { background: #008489; }
.dashboard-markdown [itemprop="prior"]::before { background: #9FD8D6; }
.dashboard-markdown [itemprop="solar"]::before { background: #FFB400; }
.dashboard-markdown [itemprop="up"]::before { background: #FF385C; }
.dashboard-markdown [itemprop="down"]::before { background: #008489; }
.dashboard-markdown [itemprop="total"]::before { background: #717171; }
.superset-chart-table .cell-bar { background-color: rgba(0, 132, 137, 0.20) !important; }
/* chart titles */
.header-title { font-size: 15px !important; font-weight: 600 !important; color: #222222; }
/* KPI cards: an accent top edge; the number in ink; the delta as coloured text with ▲▼, by meaning */
.dashboard-component-chart-holder:has([data-test-viz-type^="big_number"]):not(:has([data-test-chart-name="Data through"])) {
  border-top: 3px solid #FF385C !important; }
.header-line, .subheader-line, .superset-chart-table td { font-variant-numeric: tabular-nums; }
[data-test-viz-type="big_number"] .header-line,
[data-test-viz-type="big_number_total"] .header-line { font-size: 36px !important; line-height: 1.1 !important;
  font-weight: 600; letter-spacing: -.015em; }
[data-test-viz-type="big_number"] .header-line { color: #222222; }
[data-test-viz-type="big_number"] .subheader-line:not(.subtitle-line) { font-size: 13px !important; font-weight: 600;
  line-height: 1.4 !important; color: #6A6A6A; margin: 4px 0 2px; }
[data-test-viz-type="big_number"] .subtitle-line,
[data-test-viz-type="big_number_total"] .subheader-line,
[data-test-viz-type="big_number_total"] .subtitle-line { font-size: 12.5px !important; color: #6A6A6A; line-height: 1.4 !important; }
[data-test-viz-type="big_number_total"] .superset-legacy-chart-big-number { justify-content: flex-start !important; }
[data-test-chart-name="Data through"] .header-line { font-size: 22px !important; color: #FFFFFF !important; }
[data-test-chart-name="Lower-48 demand"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #6A6A6A !important; }
[data-test-chart-name="Lower-48 demand"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Lower-48 demand"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #6A6A6A !important; }
[data-test-chart-name="Lower-48 demand"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
[data-test-chart-name="Lower-48 evening ramp"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #995000 !important; }
[data-test-chart-name="Lower-48 evening ramp"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Lower-48 evening ramp"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #137333 !important; }
[data-test-chart-name="Lower-48 evening ramp"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
[data-test-chart-name="Batteries installed"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #137333 !important; }
[data-test-chart-name="Batteries installed"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Batteries installed"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #A50E0E !important; }
[data-test-chart-name="Batteries installed"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
[data-test-chart-name="Batteries operating"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #137333 !important; }
[data-test-chart-name="Batteries operating"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Batteries operating"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #A50E0E !important; }
[data-test-chart-name="Batteries operating"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
[data-test-chart-name="Evening ramp, median day"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #995000 !important; }
[data-test-chart-name="Evening ramp, median day"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Evening ramp, median day"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #137333 !important; }
[data-test-chart-name="Evening ramp, median day"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
[data-test-chart-name="Evening ramp, bad day"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #995000 !important; }
[data-test-chart-name="Evening ramp, bad day"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Evening ramp, bad day"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #137333 !important; }
[data-test-chart-name="Evening ramp, bad day"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
[data-test-chart-name="Baseload"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line) { color: #995000 !important; }
[data-test-chart-name="Baseload"] .superset-legacy-chart-big-number.positive .subheader-line:not(.subtitle-line)::before { content: "▲ "; }
[data-test-chart-name="Baseload"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line) { color: #6A6A6A !important; }
[data-test-chart-name="Baseload"] .superset-legacy-chart-big-number.negative .subheader-line:not(.subtitle-line)::before { content: "▼ "; }
/* tables: readable by standard (body 14 px on 36 px rows, header 13 px semibold), no vertical rules */
.superset-chart-table table thead th { background: #F0F0F0 !important; color: #222222; font-weight: 600; font-size: 13px !important; }
.superset-chart-table table th, .superset-chart-table table td { border-left: 0 !important; border-right: 0 !important; }
.superset-chart-table table tbody td { border-top: 1px solid #EFEFEF; font-size: 14px !important; height: 36px; color: #222222; }
